//! Golden-fixture test for the unified ladder-context strategy.
//!
//! The fixture is a hand-derived sequence of execution snapshots, context
//! values, and the decision each bar must produce. It covers a long and a short
//! entry, both configured exits, missing context, conflicts, late legs, a
//! non-contiguous bar, a missing execution value, and a missing Structure
//! shift. The fixture is not generated by the code under test.

use quantrule_backtest::context::{
    AgreementCode, AxisContext, LadderContext, ProgressionContext, StructureContext,
};
use quantrule_backtest::intent::StrategyPosition;
use quantrule_backtest::strategy::{
    Decision, ExitReason, LadderContextStrategy, Side, Strategy, StrategyConfig, StrategyInput,
};

const FIXTURE: &str = include_str!("fixtures/ladder_context_strategy_golden.csv");
const HEADER: &str = "bar,timeframe_secs,open_time,direction,momentum_force,structure_score,state_code,previous_state_code,contiguous,context_complete,direction_bullish,direction_bearish,momentum_bullish,momentum_bearish,conflict_count,progression,late_or_terminal,expected_decision,expected_side,expected_reason,expected_position";

#[derive(Debug)]
struct Row {
    input: StrategyInput,
    context: LadderContext,
    decision: String,
    side: String,
    reason: String,
    position: String,
}

fn number(field: &str) -> Option<f64> {
    if field.is_empty() {
        None
    } else {
        Some(
            field
                .parse::<f64>()
                .unwrap_or_else(|error| panic!("invalid number {field:?}: {error}")),
        )
    }
}

fn integer<T>(field: &str) -> T
where
    T: std::str::FromStr,
    T::Err: std::fmt::Display,
{
    field
        .parse::<T>()
        .unwrap_or_else(|error| panic!("invalid integer {field:?}: {error}"))
}

fn optional_integer<T>(field: &str) -> Option<T>
where
    T: std::str::FromStr,
    T::Err: std::fmt::Display,
{
    if field.is_empty() {
        None
    } else {
        Some(integer(field))
    }
}

fn boolean(field: &str) -> bool {
    match field {
        "true" => true,
        "false" => false,
        other => panic!("invalid boolean {other:?}"),
    }
}

fn agreement(code: u8) -> AgreementCode {
    match code {
        0 => AgreementCode::Unavailable,
        1 => AgreementCode::Bullish,
        2 => AgreementCode::Bearish,
        3 => AgreementCode::Mixed,
        other => panic!("unknown agreement code {other}"),
    }
}

fn axis(timeframes: &[u64], bullish: f64, bearish: f64, agreement: AgreementCode) -> AxisContext {
    AxisContext {
        timeframes: timeframes.to_vec(),
        bullish_count: u32::from(bullish > 0.0),
        bearish_count: u32::from(bearish > 0.0),
        neutral_count: u32::from(bullish == 0.0 && bearish == 0.0),
        weighted_value: Some(bullish - bearish),
        bullish_share: Some(bullish),
        bearish_share: Some(bearish),
        neutral_share: Some((1.0 - bullish - bearish).max(0.0)),
        agreement,
    }
}

fn load() -> Vec<Row> {
    let mut lines = FIXTURE.lines();
    assert_eq!(lines.next(), Some(HEADER), "fixture header changed");

    let mut rows = Vec::new();
    for line in lines {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 21, "wrong column count in {line:?}");
        let bar = integer::<usize>(fields[0]);
        assert_eq!(bar, rows.len(), "fixture bars must be contiguous");
        let timeframe_secs = integer::<u64>(fields[1]);
        let open_time = integer::<i64>(fields[2]);
        let input = StrategyInput::new(
            timeframe_secs,
            bar,
            open_time,
            number(fields[3]),
            number(fields[4]),
            number(fields[5]),
        )
        .with_structure(
            optional_integer::<i8>(fields[6]),
            optional_integer::<i8>(fields[7]),
        )
        .with_contiguous(boolean(fields[8]));

        let complete = boolean(fields[9]);
        let context_timeframes = if complete { vec![900] } else { Vec::new() };
        let direction = axis(
            &context_timeframes,
            number(fields[10]).unwrap_or(0.0),
            number(fields[11]).unwrap_or(0.0),
            AgreementCode::Mixed,
        );
        let momentum = axis(
            &context_timeframes,
            number(fields[12]).unwrap_or(0.0),
            number(fields[13]).unwrap_or(0.0),
            AgreementCode::Mixed,
        );
        let progression_code = agreement(integer::<u8>(fields[15]));
        let progression = match progression_code {
            AgreementCode::Bullish => axis(&context_timeframes, 1.0, 0.0, progression_code),
            AgreementCode::Bearish => axis(&context_timeframes, 0.0, 1.0, progression_code),
            _ => axis(&context_timeframes, 0.0, 0.0, progression_code),
        };
        let context = LadderContext {
            execution_timeframe_secs: timeframe_secs,
            execution_bar_index: bar,
            execution_open_time: open_time,
            execution_close_time: open_time + timeframe_secs as i64,
            context: Vec::new(),
            missing_timeframes: if complete { Vec::new() } else { vec![900] },
            direction,
            momentum,
            structure: StructureContext {
                score: AxisContext::unavailable(),
                conflict_count: integer::<u32>(fields[14]),
            },
            progression: ProgressionContext {
                direction: progression,
                stage_histogram: [0.0; 6],
                late_or_terminal_count: integer::<u32>(fields[16]),
            },
        };

        rows.push(Row {
            input,
            context,
            decision: fields[17].to_owned(),
            side: fields[18].to_owned(),
            reason: fields[19].to_owned(),
            position: fields[20].to_owned(),
        });
    }
    rows
}

fn side_label(side: Side) -> &'static str {
    match side {
        Side::Long => "long",
        Side::Short => "short",
    }
}

fn position_label(position: StrategyPosition) -> &'static str {
    match position.side {
        Some(Side::Long) => "long",
        Some(Side::Short) => "short",
        None => "flat",
    }
}

fn reason_label(reason: ExitReason) -> &'static str {
    match reason {
        ExitReason::ContextLost => "context_lost",
        ExitReason::StructureLost => "structure_lost",
    }
}

fn parts(decision: Decision) -> (&'static str, &'static str, &'static str) {
    match decision {
        Decision::Hold => ("hold", "", ""),
        Decision::Enter(entry) => ("enter", side_label(entry.intent.side), ""),
        Decision::Exit(exit) => ("exit", side_label(exit.side), reason_label(exit.reason)),
    }
}

#[test]
fn the_strategy_matches_the_golden_fixture() {
    let rows = load();
    assert_eq!(rows.len(), 21, "fixture row count changed");
    let strategy = LadderContextStrategy::new(StrategyConfig::default());
    let mut position = StrategyPosition::flat();

    for row in &rows {
        if position.is_open() {
            position.bars_held += 1;
        }
        let decision = strategy.decide(&row.input, &row.context, position);
        let (kind, side, reason) = parts(decision);
        assert_eq!(kind, row.decision, "bar {} decision", row.input.bar_index);
        assert_eq!(side, row.side, "bar {} side", row.input.bar_index);
        assert_eq!(reason, row.reason, "bar {} reason", row.input.bar_index);

        match decision {
            Decision::Enter(entry) => {
                assert_eq!(entry.bar, row.input);
                position = StrategyPosition::opened(entry.intent.side, row.input.bar_index);
            }
            Decision::Exit(exit) => {
                assert_eq!(exit.bar, row.input);
                position = StrategyPosition::flat();
            }
            Decision::Hold => {}
        }
        assert_eq!(
            position_label(position),
            row.position,
            "bar {} position",
            row.input.bar_index
        );
    }
}

#[test]
fn repeated_runs_are_identical() {
    let rows = load();
    let strategy = LadderContextStrategy::new(StrategyConfig::default());
    let run = || {
        let mut position = StrategyPosition::flat();
        rows.iter()
            .map(|row| {
                if position.is_open() {
                    position.bars_held += 1;
                }
                let decision = strategy.decide(&row.input, &row.context, position);
                match decision {
                    Decision::Enter(entry) => {
                        position = StrategyPosition::opened(entry.intent.side, row.input.bar_index);
                    }
                    Decision::Exit(_) => position = StrategyPosition::flat(),
                    Decision::Hold => {}
                }
                decision
            })
            .collect::<Vec<_>>()
    };
    let expected = run();
    for _ in 0..10 {
        assert_eq!(run(), expected);
    }
}

#[test]
fn later_bars_do_not_change_earlier_decisions() {
    let rows = load();
    let strategy = LadderContextStrategy::new(StrategyConfig::default());
    let decide = |rows: &[Row]| {
        let mut position = StrategyPosition::flat();
        rows.iter()
            .map(|row| {
                let decision = strategy.decide(&row.input, &row.context, position);
                match decision {
                    Decision::Enter(entry) => {
                        position = StrategyPosition::opened(entry.intent.side, row.input.bar_index);
                    }
                    Decision::Exit(_) => position = StrategyPosition::flat(),
                    Decision::Hold => {}
                }
                decision
            })
            .collect::<Vec<_>>()
    };

    let prefix = 13;
    assert_eq!(decide(&rows[..prefix]), decide(&rows)[..prefix]);
}
